UPDATE api_versions
SET display_name = 'Master Brand Mobil',
    updated_at = NOW()
WHERE resource_name = @master_brand_key;

INSERT INTO api_versions (resource_name, display_name, version_number, created_at, updated_at)
SELECT @master_brand_key, 'Master Brand Mobil', 1, NOW(), NULL
WHERE NOT EXISTS (
    SELECT 1
    FROM api_versions
    WHERE resource_name = @master_brand_key
);

SET @master_brand_version_id = (
    SELECT id
    FROM api_versions
    WHERE resource_name = @master_brand_key
    LIMIT 1
);

UPDATE master_data
SET data_json = @master_brand_json,
    api_version_id = @master_brand_version_id,
    deleted_at = NULL,
    updated_at = NOW()
WHERE master_key = @master_brand_key;

INSERT INTO master_data (master_key, data_json, api_version_id, created_at, updated_at, deleted_at)
SELECT @master_brand_key, @master_brand_json, @master_brand_version_id, NOW(), NULL, NULL
WHERE NOT EXISTS (
    SELECT 1
    FROM master_data
    WHERE master_key = @master_brand_key
);
